from pathlib import Path
from typing import Final

import pytest

NOTES_DIR: Final[str] = "notes"


def first_readable(names: list[str]) -> str:
    """Return the text of the first readable file in NOTES_DIR named in names.

    Each name is resolved relative to NOTES_DIR. Names that would resolve
    outside NOTES_DIR (absolute paths, '..' segments, symlinks leading out,
    embedded NUL bytes) are skipped. Missing or unreadable files are skipped.
    Returns "" when no name yields a readable file.
    """
    base = (Path.cwd() / NOTES_DIR).resolve()
    for name in names:
        if "\x00" in name:
            continue
        candidate = (base / name).resolve()
        if not candidate.is_relative_to(base):
            continue
        if not candidate.is_file():
            continue
        try:
            return candidate.read_text(encoding="utf-8")
        except (OSError, UnicodeDecodeError):
            continue
    return ""


def _write(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8")


def test_returns_first_readable_in_order(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    monkeypatch.chdir(tmp_path)
    _write(tmp_path / NOTES_DIR / "a.txt", "A")
    _write(tmp_path / NOTES_DIR / "b.txt", "B")
    assert first_readable(["b.txt", "a.txt"]) == "B"


def test_skips_missing_files(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.chdir(tmp_path)
    _write(tmp_path / NOTES_DIR / "a.txt", "A")
    assert first_readable(["missing.txt", "a.txt"]) == "A"


def test_none_readable_returns_empty(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    monkeypatch.chdir(tmp_path)
    (tmp_path / NOTES_DIR).mkdir()
    assert first_readable(["x.txt", "y.txt"]) == ""


def test_empty_list_returns_empty(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    monkeypatch.chdir(tmp_path)
    (tmp_path / NOTES_DIR).mkdir()
    assert first_readable([]) == ""


def test_directory_name_is_not_readable(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    monkeypatch.chdir(tmp_path)
    (tmp_path / NOTES_DIR / "sub").mkdir(parents=True)
    _write(tmp_path / NOTES_DIR / "a.txt", "A")
    assert first_readable(["sub", "a.txt"]) == "A"


def test_parent_traversal_is_refused(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    monkeypatch.chdir(tmp_path)
    _write(tmp_path / "secret.txt", "S")
    (tmp_path / NOTES_DIR).mkdir()
    assert first_readable(["../secret.txt"]) == ""
    assert first_readable(["sub/../../secret.txt"]) == ""


def test_absolute_path_is_refused(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    monkeypatch.chdir(tmp_path)
    _write(tmp_path / "secret.txt", "S")
    (tmp_path / NOTES_DIR).mkdir()
    assert first_readable([str(tmp_path / "secret.txt")]) == ""


def test_sibling_prefix_is_refused(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    monkeypatch.chdir(tmp_path)
    _write(tmp_path / "notes2" / "x.txt", "X")
    (tmp_path / NOTES_DIR).mkdir()
    assert first_readable(["../notes2/x.txt"]) == ""


def test_traversal_does_not_stop_later_valid_names(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    monkeypatch.chdir(tmp_path)
    _write(tmp_path / "secret.txt", "S")
    _write(tmp_path / NOTES_DIR / "ok.txt", "OK")
    assert first_readable(["../secret.txt", "ok.txt"]) == "OK"


def test_nul_byte_name_does_not_raise(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    monkeypatch.chdir(tmp_path)
    _write(tmp_path / NOTES_DIR / "a.txt", "A")
    assert first_readable(["a\x00.txt", "a.txt"]) == "A"
    assert first_readable(["a\x00.txt"]) == ""


def test_symlink_pointing_outside_is_refused(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    monkeypatch.chdir(tmp_path)
    _write(tmp_path / "secret.txt", "S")
    (tmp_path / NOTES_DIR).mkdir()
    link = tmp_path / NOTES_DIR / "link.txt"
    try:
        link.symlink_to(tmp_path / "secret.txt")
    except OSError:
        pytest.skip("symlinks not supported here")
    assert first_readable(["link.txt"]) == ""
